import React, { useState, useEffect } from 'react';
import { Plus, Search, X, Megaphone, Calendar, MapPin, Users, Info, Edit, Trash2 } from 'lucide-react';
import api from '../../services/api';
import toast from 'react-hot-toast';
import './Modules.css';

const CommunityOutreach = () => {
  const [activities, setActivities] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);

  // Form State
  const [formData, setFormData] = useState({
    activity_name: '',
    participants: 0,
    date: '',
    location: '',
    objectives: '',
    outcomes: '',
    stigma_reduction_feedback: '',
    notes: '',
  });

  const loadActivities = async () => {
    setLoading(true);
    try {
      const response = await api.get('/community-outreach/');
      setActivities(Array.isArray(response.data) ? response.data : response.data.results || []);
    } catch (error) {
      console.error('Error loading community outreach:', error);
      toast.error('Failed to load community outreach activities.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadActivities();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === 'participants' ? parseInt(value) || 0 : value,
    }));
  };

  const handleClose = () => {
    setShowModal(false);
    setEditingId(null);
    setFormData({
      activity_name: '',
      participants: 0,
      date: '',
      location: '',
      objectives: '',
      outcomes: '',
      stigma_reduction_feedback: '',
      notes: '',
    });
  };

  const handleEdit = (item) => {
    setFormData({
      activity_name: item.activity_name || '',
      participants: item.participants || 0,
      date: item.date || '',
      location: item.location || '',
      objectives: item.objectives || '',
      outcomes: item.outcomes || '',
      stigma_reduction_feedback: item.stigma_reduction_feedback || '',
      notes: item.notes || '',
    });
    setEditingId(item.id);
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this outreach activity?')) {
      try {
        await api.delete(`/community-outreach/${id}/`);
        toast.success('Outreach activity deleted successfully!');
        loadActivities();
      } catch (error) {
        console.error('Error deleting activity:', error);
        toast.error('Failed to delete activity.');
      }
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await api.put(`/community-outreach/${editingId}/`, formData);
        toast.success('Community outreach activity updated successfully!');
      } else {
        await api.post('/community-outreach/', formData);
        toast.success('Community outreach activity recorded successfully!');
      }
      handleClose();
      loadActivities();
    } catch (error) {
      console.error('Error saving outreach activity:', error);
      const detail = error.response?.data ? JSON.stringify(error.response.data) : 'Failed to save.';
      toast.error('Error: ' + detail);
    } finally {
      setSaving(false);
    }
  };

  // Filtered list
  const filteredActivities = activities.filter(
    (item) =>
      item.activity_name?.toLowerCase().includes(search.toLowerCase()) ||
      item.location?.toLowerCase().includes(search.toLowerCase()) ||
      item.objectives?.toLowerCase().includes(search.toLowerCase())
  );

  // Stats
  const totalActivities = activities.length;
  const totalParticipants = activities.reduce((sum, a) => sum + (a.participants || 0), 0);
  const averageParticipants = activities.length
    ? Math.round(totalParticipants / activities.length)
    : 0;

  return (
    <div className="module-container">
      <div className="module-header">
        <div>
          <h1>Community Outreach</h1>
          <p>Document community advocacy activities, awareness meetings, and trace public engagement metrics.</p>
        </div>
        <button className="btn-primary" onClick={() => setShowModal(true)}>
          <Plus size={18} /> New Outreach Activity
        </button>
      </div>

      {/* Stats Cards */}
      <div className="stats-grid">
        <div className="stats-card">
          <h3>Outreach Events</h3>
          <div className="value">{totalActivities}</div>
        </div>
        <div className="stats-card">
          <h3>Total Engaged</h3>
          <div className="value">{totalParticipants}</div>
        </div>
        <div className="stats-card">
          <h3>Avg. Engagement / Event</h3>
          <div className="value">{averageParticipants}</div>
        </div>
      </div>

      {/* Controls */}
      <div className="controls-row">
        <div className="search-input-wrapper">
          <Search size={18} className="search-icon" />
          <input
            type="text"
            placeholder="Search by event title, location, or objectives..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* Data Table */}
      <div className="table-card">
        {loading ? (
          <div style={{ padding: '40px', textAlign: 'center', color: '#5a5c74' }}>Loading activities data...</div>
        ) : filteredActivities.length === 0 ? (
          <div className="empty-state">
            <Megaphone size={48} className="empty-state-icon" />
            <p>No community activities found. Click "New Outreach Activity" to add one.</p>
          </div>
        ) : (
          <table className="responsive-table">
            <thead>
              <tr>
                <th>Activity / Event Name</th>
                <th>Date</th>
                <th>Location</th>
                <th>Participants</th>
                <th>Objectives</th>
                <th>Outcomes</th>
                <th style={{ textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredActivities.map((item) => (
                <tr key={item.id}>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600, color: '#0f2d60' }}>
                      <Megaphone size={14} style={{ color: '#1c7ec4' }} />
                      {item.activity_name}
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#5a5c74' }}>
                      <Calendar size={14} />
                      {item.date}
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <MapPin size={14} style={{ color: '#8890a6' }} />
                      {item.location}
                    </div>
                  </td>
                  <td>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontWeight: 600 }}>
                      <Users size={14} style={{ color: '#8890a6' }} />
                      {item.participants}
                    </div>
                  </td>
                  <td style={{ maxWidth: '180px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'normal' }} title={item.objectives}>
                    {item.objectives}
                  </td>
                  <td style={{ maxWidth: '180px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'normal' }} title={item.outcomes}>
                    {item.outcomes}
                  </td>
                  <td>
                    <div className="action-buttons-group">
                      <button 
                        className="btn-icon" 
                        title="Edit Event"
                        onClick={() => handleEdit(item)}
                      >
                        <Edit size={14} style={{ color: '#2F9E68' }} />
                      </button>
                      <button 
                        className="btn-icon" 
                        title="Delete Event"
                        onClick={() => handleDelete(item.id)}
                      >
                        <Trash2 size={14} style={{ color: '#C94B4B' }} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Form Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2>{editingId ? 'Edit Outreach Event' : 'Record New Community Activity'}</h2>
              <button className="close-btn" onClick={handleClose}>
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body">
                <div className="form-grid">
                  <div className="form-group full-width">
                    <label>Activity / Event Name</label>
                    <input
                      type="text"
                      name="activity_name"
                      placeholder="e.g. Disability Awareness Dialogue Meeting"
                      value={formData.activity_name}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Date Conducted</label>
                    <input
                      type="date"
                      name="date"
                      value={formData.date}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Location / Venue</label>
                    <input
                      type="text"
                      name="location"
                      placeholder="e.g. Kasawo Sub-county Headquarters"
                      value={formData.location}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Number of Participants / Attendants</label>
                    <input
                      type="number"
                      name="participants"
                      value={formData.participants}
                      onChange={handleInputChange}
                      min="0"
                      required
                    />
                  </div>
                  <div className="form-group full-width">
                    <label>Campaign Objectives</label>
                    <textarea
                      name="objectives"
                      rows="2"
                      placeholder="e.g. Sensitize local leaders on pediatric disability support and eliminate local stigma..."
                      value={formData.objectives}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group full-width">
                    <label>Key Outcomes</label>
                    <textarea
                      name="outcomes"
                      rows="2"
                      placeholder="e.g. Local chief agreed to refer child cases to outreach, 3 children registered..."
                      value={formData.outcomes}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group full-width">
                    <label>Stigma Reduction & Feedback Indicators</label>
                    <textarea
                      name="stigma_reduction_feedback"
                      rows="2"
                      placeholder="Enter specific comments or community attitude shifts observed..."
                      value={formData.stigma_reduction_feedback}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="form-group full-width">
                    <label>General Notes / Recommendations</label>
                    <textarea
                      name="notes"
                      rows="2"
                      placeholder="Enter follow-up suggestions, materials requested..."
                      value={formData.notes}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn-secondary" onClick={handleClose}>
                  Cancel
                </button>
                <button type="submit" className="btn-primary" disabled={saving}>
                  {saving ? 'Saving...' : (editingId ? 'Update Activity' : 'Save Activity')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CommunityOutreach;
